interface Employee {
  employee_id: string;
  name: string;
  department: string;
  salary: number;
  start_date: string;
  rating: number;
}

const employees: Employee[] = [];
for (let i = 1; i < lines.length; i++) {
  const parts = lines[i].split(',');
  if (parts.length >= 6) {
    employees.push({
      employee_id: parts[0],
      name: parts[1],
      department: parts[2],
      salary: parseFloat(parts[3]),
      start_date: parts[4],
      rating: parseFloat(parts[5]),
    });
  }
}

function formatInt(n: number): string {
  return Math.round(n).toLocaleString('en-US');
}

function formatFloat(n: number): string {
  return n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// Average salary by department
const deptSalaries: Map<string, number[]> = new Map();
for (const emp of employees) {
  if (!deptSalaries.has(emp.department)) {
    deptSalaries.set(emp.department, []);
  }
  deptSalaries.get(emp.department)!.push(emp.salary);
}

const deptAvgs: { dept: string; avg: number }[] = [];
for (const [dept, salaries] of deptSalaries) {
  const avg = salaries.reduce((a, b) => a + b, 0) / salaries.length;
  deptAvgs.push({ dept, avg });
}
deptAvgs.sort((a, b) => a.dept.localeCompare(b.dept));

