for (const [dept, salaries] of deptSalaries) {
  if (salaries.length > 2) {
    deptCounts.push({ dept, count: salaries.length });
  }
}
deptCounts.sort((a, b) => a.dept.localeCompare(b.dept));

// Total budget
const totalBudget = employees.reduce((sum, emp) => sum + emp.salary, 0);

// Output
console.log('=== Salary Report ===');
console.log('');
console.log('Average Salary by Department:');
for (const { dept, avg } of deptAvgs) {
  console.log(`  ${dept}: $${formatFloat(avg)}`);
}
console.log('');
console.log(`Highest Paid: ${highestPaid.name} ($${formatInt(highestPaid.salary)})`);
console.log('');
console.log('Departments with >2 employees:');
for (const { dept, count } of deptCounts) {
  console.log(`  ${dept} (${count} employees)`);
}
console.log('');
console.log(`Total Budget: $${formatInt(totalBudget)}`);

