import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new FileReader("/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_a7ernmag/employees.csv"));
        String line = br.readLine(); // skip header

        Map<String, List<Double>> deptSalaries = new TreeMap<>();
        Map<String, Integer> deptCount = new TreeMap<>();
        double totalBudget = 0;
        double maxSalary = -1;
        String maxName = "";

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split(",");
            String name = parts[1].trim();
            String dept = parts[2].trim();
            double salary = Double.parseDouble(parts[3].trim());

            deptSalaries.computeIfAbsent(dept, k -> new ArrayList<>()).add(salary);
            deptCount.merge(dept, 1, Integer::sum);
            totalBudget += salary;

            if (salary > maxSalary) {
                maxSalary = salary;
                maxName = name;
            }
        }
        br.close();

        System.out.println("=== Salary Report ===");
        System.out.println();

        System.out.println("Average Salary by Department:");
        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            double avg = entry.getValue().stream().mapToDouble(Double::doubleValue).average().orElse(0);
            System.out.printf("  %s: $%,.2f%n", entry.getKey(), avg);
        }
        System.out.println();

        System.out.printf("Highest Paid: %s ($%,d)%n", maxName, (long) maxSalary);
        System.out.println();

        System.out.println("Departments with >2 employees:");
        for (Map.Entry<String, Integer> entry : deptCount.entrySet()) {
            if (entry.getValue() > 2) {
                System.out.printf("  %s (%d employees)%n", entry.getKey(), entry.getValue());
            }
        }
        System.out.println();

        System.out.printf("Total Budget: $%,d%n", (long) totalBudget);
    }
}

