import * as fs from 'fs';

type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue };

function isObject(val: JsonValue): val is { [key: string]: JsonValue } {
    return val !== null && typeof val === 'object' && !Array.isArray(val);
}

function isArray(val: JsonValue): val is JsonValue[] {
    return Array.isArray(val);
}

function deepMerge(a: JsonValue, b: JsonValue): JsonValue {
    if (isObject(a) && isObject(b)) {
        const result: { [key: string]: JsonValue } = {};
        const keys = new Set<string>([...Object.keys(a), ...Object.keys(b)]);
        for (const key of keys) {
            if (key in a && key in b) {
                result[key] = deepMerge(a[key], b[key]);
            } else if (key in a) {
                result[key] = a[key];
            } else {
                result[key] = b[key];
            }
        }
        return result;
    }
    if (isArray(a) && isArray(b)) {
        const result: JsonValue[] = [];
        const seen = new Set<string>();
        for (const item of a) {
            const key = JSON.stringify(item);
            if (!seen.has(key)) {
                seen.add(key);
                result.push(item);
            }
        }
        for (const item of b) {
            const key = JSON.stringify(item);
            if (!seen.has(key)) {
                seen.add(key);
                result.push(item);
            }
        }
        return result;
    }
    return b;
}

function sortKeys(val: JsonValue): JsonValue {
    if (isObject(val)) {
        const sorted: { [key: string]: JsonValue } = {};
        const keys = Object.keys(val).sort();
        for (const key of keys) {
            sorted[key] = sortKeys(val[key]);
        }
        return sorted;
    }
    if (isArray(val)) {
        return val.map(sortKeys);
    }
    return val;
}

