import Foundation

let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_a7ernmag/employees.csv"
let content = try! String(contentsOfFile: path, encoding: .utf8)
let lines = content.components(separatedBy: .newlines).filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

guard lines.count > 1 else { fatalError("Empty CSV") }

var departments: [String: [Double]] = [:]
var employees: [(name: String, salary: Double)] = []
var deptCounts: [String: Int] = [:]
var totalBudget: Double = 0

func parseCSVLine(_ line: String) -> [String] {
    var fields: [String] = []
    var current = ""
    var inQuotes = false
    for ch in line {
        if ch == "\"" {
            inQuotes.toggle()
        } else if ch == "," && !inQuotes {
            fields.append(current.trimmingCharacters(in: .whitespaces))
            current = ""
        } else {
            current.append(ch)
        }
    }
    fields.append(current.trimmingCharacters(in: .whitespaces))
    return fields
}

for line in lines.dropFirst() {
    let parts = parseCSVLine(line)
    guard parts.count >= 4 else { continue }
    let name = parts[1]
    let department = parts[2]
    let salary = Double(parts[3]) ?? 0

    departments[department, default: []].append(salary)
    employees.append((name: name, salary: salary))
    deptCounts[department, default: 0] += 1
    totalBudget += salary
}

func formatInt(_ value: Double) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.groupingSeparator = ","
    formatter.maximumFractionDigits = 0
    formatter.minimumFractionDigits = 0
    return formatter.string(from: NSNumber(value: Int(value.rounded()))) ?? "\(Int(value.rounded()))"
}

func formatDecimal(_ value: Double) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.groupingSeparator = ","
    formatter.maximumFractionDigits = 2
    formatter.minimumFractionDigits = 2
    return formatter.string(from: NSNumber(value: value)) ?? String(format: "%.2f", value)
}

print("=== Salary Report ===")
print("")
print("Average Salary by Department:")
for dept in departments.keys.sorted() {
    let salaries = departments[dept]!
    let avg = salaries.reduce(0, +) / Double(salaries.count)
    print("  \(dept): $\(formatDecimal(avg))")
