import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_a7ernmag/app.log";

        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> componentErrors = new HashMap<>();
        Set<String> uniqueErrorMessages = new TreeSet<>();
        Map<String, Integer> hourCounts = new HashMap<>();

        Pattern pattern = Pattern.compile("\\[(\\d{4}-\\d{2}-\\d{2}) (\\d{2}):(\\d{2}:\\d{2})\\] (\\w+) \\(([^)]+)\\) - (.+)");

        BufferedReader br = new BufferedReader(new FileReader(filePath));
        String line;
        while ((line = br.readLine()) != null) {
            Matcher m = pattern.matcher(line);
            if (m.matches()) {
                String hour = m.group(2);
                String level = m.group(4);
                String component = m.group(5);
                String message = m.group(6);

                levelCounts.put(level, levelCounts.getOrDefault(level, 0) + 1);
                hourCounts.put(hour, hourCounts.getOrDefault(hour, 0) + 1);

                if (level.equals("ERROR")) {
                    componentErrors.put(component, componentErrors.getOrDefault(component, 0) + 1);
                    uniqueErrorMessages.add(message);
                }
            }
        }
