use std::collections::HashMap;
use std::fs;

fn format_commas(n: i64) -> String {
    let s = n.to_string();
    let mut result = String::new();
    let len = s.len();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result
}

fn format_commas_f64(n: f64) -> String {
    let is_neg = n < 0.0;
    let abs_n = n.abs();
    let mut integer_part = abs_n.floor() as i64;
    let mut decimal_part = ((abs_n - integer_part as f64) * 100.0).round() as i64;
    if decimal_part >= 100 {
        integer_part += 1;
        decimal_part -= 100;
    }
    let int_str = format_commas(integer_part);
    format!("{}{}.{:02}", if is_neg { "-" } else { "" }, int_str, decimal_part)
}

fn split_csv(line: &str) -> Vec<String> {
    let mut fields = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;
    let chars: Vec<char> = line.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '"' {
            if in_quotes && i + 1 < chars.len() && chars[i + 1] == '"' {
                current.push('"');
                i += 2;
                continue;
            }
            in_quotes = !in_quotes;
        } else if c == ',' && !in_quotes {
            fields.push(current.clone());
            current.clear();
        } else {
            current.push(c);
        }
        i += 1;
    }
    fields.push(current);
    fields
}

fn main() {
    let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_a7ernmag/employees.csv";
    let content = fs::read_to_string(path).expect("Failed to read CSV file");

    let mut dept_salaries: HashMap<String, Vec<f64>> = HashMap::new();
    let mut dept_count: HashMap<String, usize> = HashMap::new();
    let mut highest_paid_name = String::new();
    let mut highest_paid_salary: f64 = 0.0;
    let mut total_budget: f64 = 0.0;

    let mut first_line = true;
    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        if first_line {
            first_line = false;
            continue;
        }

        let fields = split_csv(line);
        if fields.len() < 6 {
            continue;
        }

        let name = fields[1].trim().to_string();
        let department = fields[2].trim().to_string();
        let salary: f64 = fields[3].trim().parse().unwrap_or(0.0);

        dept_salaries
            .entry(department.clone())
            .or_insert_with(Vec::new)
            .push(salary);
        *dept_count.entry(department).or_insert(0) += 1;

        if salary > highest_paid_salary {
            highest_paid_salary = salary;
            highest_paid_name = name;
        }

        total_budget += salary;
    }

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");

    let mut depts: Vec<&String> = dept_salaries.keys().collect();
    depts.sort();

    for dept in &depts {
        let salaries = dept_salaries.get(*dept).unwrap();
        let avg = salaries.iter().sum::<f64>() / salaries.len() as f64;
        println!("  {}: ${}", dept, format_commas_f64(avg));
    }

    println!();
    println!(
        "Highest Paid: {} (${})",
        highest_paid_name,
        format_commas(highest_paid_salary as i64)
    );

    println!();
    println!("Departments with >2 employees:");

    let mut depts_over_2: Vec<(&String, usize)> = dept_count
        .iter()
        .filter(|(_, &count)| count > 2)
        .map(|(k, &v)| (k, v))
        .collect();
    depts_over_2.sort_by_key(|(k, _)| k.as_str());

    for (dept, count) in &depts_over_2 {
        println!("  {} ({} employees)", dept, count);
    }

    println!();
    println!("Total Budget: ${}", format_commas(total_budget as i64));
}

