#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_LINE 4096
#define MAX_DEPTS 256

typedef struct {
    char name[256];
    char dept[256];
    double salary;
} Employee;

typedef struct {
    char dept[256];
    double total;
    int count;
} DeptInfo;

static void format_int_with_commas(long long val, char *buf, size_t bufsz) {
    char tmp[64];
    int neg = 0;
    if (val < 0) { neg = 1; val = -val; }
    snprintf(tmp, sizeof(tmp), "%lld", val);
    int len = strlen(tmp);
    int pos = 0;
    int first_group = len % 3;
    if (first_group == 0) first_group = 3;
    int i = 0;
    if (neg && pos < (int)bufsz - 1) buf[pos++] = '-';
    for (i = 0; i < len; i++) {
        if (pos >= (int)bufsz - 1) break;
        if (i > 0 && (len - i) % 3 == 0) buf[pos++] = ',';
        buf[pos++] = tmp[i];
    }
    buf[pos] = '\0';
}

static void format_double_with_commas(double val, char *buf, size_t bufsz) {
    long long int_part = (long long)val;
    double frac = val - (double)int_part;
    if (frac < 0) frac = -frac;
    int cents = (int)(frac * 100.0 + 0.5);
    if (cents >= 100) { int_part += cents / 100; cents %= 100; }
    char int_buf[64];
    format_int_with_commas(int_part, int_buf, sizeof(int_buf));
    snprintf(buf, bufsz, "%s.%02d", int_buf, cents);
}

static int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

