    double total_budget = 0.0;
    double max_salary = -1.0;
    char max_name[256] = "";

    /* skip header */
    if (fgets(line, MAX_LINE, f)) { /* skip */ }

    while (fgets(line, MAX_LINE, f)) {
        /* strip trailing newline */
        size_t len = strlen(line);
        while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) {
            line[--len] = '\0';
        }
        if (len == 0) continue;

        /* parse CSV: employee_id,name,department,salary,start_date,rating */
        char *fields[6];
        int nf = 0;
        char *tok = line;
        for (int i = 0; i < 6; i++) {
            fields[i] = tok;
            nf++;
            char *comma = strchr(tok, ',');
            if (!comma) break;
            *comma = '\0';
            tok = comma + 1;
        }
        if (nf < 4) continue;

        /* store employee */
        if (emp_count >= emp_cap) {
            emp_cap = emp_cap == 0 ? 64 : emp_cap * 2;
