        for (int d = 0; d < dept_count; d++) {
            if (strcmp(depts[d].dept, fields[2]) == 0) {
                depts[d].total += emps[emp_count-1].salary;
                depts[d].count++;
                found = 1;
                break;
            }
        }
        if (!found && dept_count < MAX_DEPTS) {
            strncpy(depts[dept_count].dept, fields[2], 255);
            depts[dept_count].dept[255] = '\0';
            depts[dept_count].total = emps[emp_count-1].salary;
            depts[dept_count].count = 1;
            dept_count++;
