    // Extract hour from "YYYY-MM-DD HH:MM:SS"
    let hourStart = timestampStr.index(timestampStr.startIndex, offsetBy: 11)
    let hourEnd = timestampStr.index(timestampStr.startIndex, offsetBy: 13)
    let hourStr = String(timestampStr[hourStart..<hourEnd])
    hourCounts[hourStr, default: 0] += 1

    // After "] " comes "LEVEL (component) - message"
    let restStart = line.index(closeBracketIdx, offsetBy: 2)
    guard restStart < line.endIndex else { continue }
    let rest = String(line[restStart...])

    // Parse LEVEL (first word)
    guard let spaceIdx = rest.firstIndex(of: " ") else { continue }
    let level = String(rest[rest.startIndex..<spaceIdx])
    levelCounts[level, default: 0] += 1

    // After space, expect "(component) - message"
    let afterLevel = String(rest[rest.index(after: spaceIdx)...])

    guard afterLevel.hasPrefix("(") else { continue }
    guard let closeParenIdx = afterLevel.firstIndex(of: ")") else { continue }
    let component = String(afterLevel[afterLevel.index(after: afterLevel.startIndex)..<closeParenIdx])

    // After ") - " comes message
    let msgStart = afterLevel.index(closeParenIdx, offsetBy: 3)
    guard msgStart < afterLevel.endIndex else { continue }
    let message = String(afterLevel[msgStart...]).trimmingCharacters(in: .whitespaces)

    if level == "ERROR" {
        componentErrorCounts[component, default: 0] += 1
        uniqueErrorMessages.insert(message)
    }
}

