if let comp = componentErrorCounts.max(by: { $0.value < $1.value }) {
    print("Component with Most Errors: \(comp.key) (\(comp.value) errors)")
}
print("")

print("Unique Error Messages:")
for msg in uniqueErrorMessages.sorted() {
    print("  - \(msg)")
}
print("")

if let hour = hourCounts.max(by: { $0.value < $1.value }) {
    print("Busiest Hour: \(hour.key):00 (\(hour.value) entries)")
}

