public class Main {
    public static void main(String[] args) throws Exception {
        URL url = new URL("http://127.0.0.1:18924/api/products");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }
        reader.close();
        String json = sb.toString().trim();

        List<Map<String, Object>> products = parseJsonArray(json);

        List<Map<String, Object>> filtered = new ArrayList<>();
        for (Map<String, Object> p : products) {
            double price = ((Number) p.get("price")).doubleValue();
            if (price > 50.00) {
                filtered.add(p);
            }
        }

        filtered.sort((a, b) -> ((String) a.get("name")).compareTo((String) b.get("name")));

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();
        double total = 0.0;
        for (Map<String, Object> p : filtered) {
            double price = ((Number) p.get("price")).doubleValue();
            System.out.printf("%s: $%.2f%n", p.get("name"), price);
            total += price;
        }
        System.out.println();
        System.out.println("Count: " + filtered.size());
        System.out.printf("Total: $%.2f%n", total);
    }

    static int pos;
    static String src;

    static List<Map<String, Object>> parseJsonArray(String s) {
        src = s;
        pos = 0;
        skipWhitespace();
        expect('[');
        List<Map<String, Object>> list = new ArrayList<>();
        skipWhitespace();
        if (peek() == ']') { pos++; return list; }
        while (true) {
            list.add(parseJsonObject());
            skipWhitespace();
            if (peek() == ',') { pos++; skipWhitespace(); }
            else break;
        }
        expect(']');
        return list;
    }

    static Map<String, Object> parseJsonObject() {
        skipWhitespace();
        expect('{');
        Map<String, Object> map = new LinkedHashMap<>();
        skipWhitespace();
        if (peek() == '}') { pos++; return map; }
        while (true) {
            skipWhitespace();
            String key = parseJsonString();
            skipWhitespace();
            expect(':');
            skipWhitespace();
            Object val = parseJsonValue();
            map.put(key, val);
            skipWhitespace();
            if (peek() == ',') { pos++; skipWhitespace(); }
            else break;
        }
        expect('}');
        return map;
    }

    static Object parseJsonValue() {
        skipWhitespace();
        char c = peek();
        if (c == '"') return parseJsonString();
        if (c == '[') {
            pos++;
            List<Object> arr = new ArrayList<>();
            skipWhitespace();
            if (peek() == ']') { pos++; return arr; }
            while (true) {
                arr.add(parseJsonValue());
                skipWhitespace();
                if (peek() == ',') { pos++; }
                else break;
            }
            expect(']');
            return arr;
        }
        if (c == '{') return parseJsonObject();
        if (c == 't') { pos += 4; return Boolean.TRUE; }
        if (c == 'f') { pos += 5; return Boolean.FALSE; }
        if (c == 'n') { pos += 4; return null; }
        return parseJsonNumber();
    }

    static String parseJsonString() {
        expect('"');
        StringBuilder sb = new StringBuilder();
        while (pos < src.length()) {
            char c = src.charAt(pos);
            if (c == '"') { pos++; return sb.toString(); }
            if (c == '\\') {
                pos++;
                char esc = src.charAt(pos);
                switch (esc) {
                    case '"': sb.append('"'); break;
                    case '\\': sb.append('\\'); break;
                    case '/': sb.append('/'); break;
                    case 'n': sb.append('\n'); break;
                    case 't': sb.append('\t'); break;
                    case 'r': sb.append('\r'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'u':
                        String hex = src.substring(pos + 1, pos + 5);
                        sb.append((char) Integer.parseInt(hex, 16));
                        pos += 4;
                        break;
                    default: sb.append(esc);
                }
                pos++;
            } else {
                sb.append(c);
                pos++;
            }
        }
        return sb.toString();
    }

    static Number parseJsonNumber() {
        int start = pos;
        if (peek() == '-') pos++;
        while (pos < src.length() && Character.isDigit(src.charAt(pos))) pos++;
        boolean isFloat = false;
        if (pos < src.length() && src.charAt(pos) == '.') {
            isFloat = true;
            pos++;
            while (pos < src.length() && Character.isDigit(src.charAt(pos))) pos++;
        }
        if (pos < src.length() && (src.charAt(pos) == 'e' || src.charAt(pos) == 'E')) {
            isFloat = true;
            pos++;
            if (pos < src.length() && (src.charAt(pos) == '+' || src.charAt(pos) == '-')) pos++;
            while (pos < src.length() && Character.isDigit(src.charAt(pos))) pos++;
        }
        String numStr = src.substring(start, pos);
        if (isFloat) return Double.parseDouble(numStr);
        long val = Long.parseLong(numStr);
        if (val >= Integer.MIN_VALUE && val <= Integer.MAX_VALUE) return (int) val;
        return val;
    }

    static void skipWhitespace() {
        while (pos < src.length() && Character.isWhitespace(src.charAt(pos))) pos++;
    }

    static char peek() {
        return pos < src.length() ? src.charAt(pos) : '\0';
    }

    static void expect(char c) {
        if (pos < src.length() && src.charAt(pos) == c) pos++;
    }
