    var minDist = .max
    var minNode = ""
    var found = false
    for node in nodes {
        if !visited.contains(node) && dist[node]! < minDist {
            minDist = dist[node]!
            minNode = node
            found = true
        }
    }
    if !found { break }
    visited.insert(minNode)
    for (neighbor, weight) in adj[minNode, default: []] {
        if !visited.contains(neighbor) {
