import * as http from 'http';

interface Product {
  id: number;
  name: string;
  price: number;
  category: string;
  stock: number;
}

function httpGet(url: string): Promise<string> {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let data = '';
      res.on('data', (chunk: string) => { data += chunk; });
      res.on('end', () => { resolve(data); });
      res.on('error', (err: Error) => { reject(err); });
    }).on('error', (err: Error) => { reject(err); });
  });
}

async function main(): Promise<void> {
  const response: string = await httpGet('http://127.0.0.1:18924/api/products');
  const products: Product[] = JSON.parse(response);

  const filtered: Product[] = products.filter((p: Product) => p.price > 50.00);
  filtered.sort((a: Product, b: Product) => a.name.localeCompare(b.name));

