        int nodesKey = json.indexOf("\"nodes\"");
        int nodesArrStart = json.indexOf('[', nodesKey);
        int nodesArrEnd = json.indexOf(']', nodesArrStart);
        String nodesStr = json.substring(nodesArrStart + 1, nodesArrEnd);
        Matcher nm = Pattern.compile("\"([^\"]+)\"").matcher(nodesStr);
        while (nm.find()) {
            nodes.add(nm.group(1));
        }

        Map<String, Integer> nodeIndex = new HashMap<>();
        Map<String, List<int[]>> adjacency = new HashMap<>();
        for (int i = 0; i < nodes.size(); i++) {
            nodeIndex.put(nodes.get(i), i);
            adjacency.put(nodes.get(i), new ArrayList<>());
        }

        // Parse edges
        int edgesKey = json.indexOf("\"edges\"");
        int edgesArrStart = json.indexOf('[', edgesKey);
        int edgesArrEnd = json.lastIndexOf(']');
        String edgesStr = json.substring(edgesArrStart + 1, edgesArrEnd);

        // Find each edge object {...}
        Pattern objPattern = Pattern.compile("\\{[^{}]*\\}");
        Matcher objMatcher = objPattern.matcher(edgesStr);
        while (objMatcher.find()) {
            String obj = objMatcher.group();
            String from = null, to = null;
            int weight = 0;
            Matcher fm = Pattern.compile("\"from\"\\s*:\\s*\"([^\"]+)\"").matcher(obj);
            if (fm.find()) from = fm.group(1);
            Matcher tm = Pattern.compile("\"to\"\\s*:\\s*\"([^\"]+)\"").matcher(obj);
            if (tm.find()) to = tm.group(1);
            Matcher wm = Pattern.compile("\"weight\"\\s*:\\s*(-?\\d+)").matcher(obj);
            if (wm.find()) weight = Integer.parseInt(wm.group(1));
            if (from != null && to != null) {
                adjacency.get(from).add(new int[]{nodeIndex.get(to), weight});
                adjacency.get(to).add(new int[]{nodeIndex.get(from), weight});
            }
        }

        // Dijkstra's algorithm
        int n = nodes.size();
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        int startIdx = nodeIndex.get("A");
        dist[startIdx] = 0;

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[1], b[1]));
        pq.offer(new int[]{startIdx, 0});

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int u = curr[0];
            int d = curr[1];
            if (d > dist[u]) continue;
            String uName = nodes.get(u);
            for (int[] edge : adjacency.get(uName)) {
                int v = edge[0];
                int w = edge[1];
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.offer(new int[]{v, dist[v]});
                }
            }
        }

        // Output
        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        List<String> sortedNodes = new ArrayList<>(nodes);
        Collections.sort(sortedNodes);
        for (String node : sortedNodes) {
            System.out.println("A -> " + node + ": " + dist[nodeIndex.get(node)]);
        }
    }
}

