static char *http_get(const char *host, int port, const char *path) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) return NULL;

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    inet_pton(AF_INET, host, &addr.sin_addr);

    if (connect(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        close(sock);
        return NULL;
    }

    char request[4096];
    snprintf(request, sizeof(request),
        "GET %s HTTP/1.1\r\nHost: %s:%d\r\nConnection: close\r\n\r\n",
        path, host, port);

    send(sock, request, strlen(request), 0);

    size_t buf_size = 65536;
    size_t buf_len = 0;
    char *buf = (char *)malloc(buf_size);
    ssize_t n;
    while ((n = recv(sock, buf + buf_len, buf_size - buf_len, 0)) > 0) {
        buf_len += n;
        if (buf_len + 1 >= buf_size) {
            buf_size *= 2;
            buf = (char *)realloc(buf, buf_size);
        }
    }
    close(sock);
    buf[buf_len] = '\0';

    /* Find end of headers */
    char *body = strstr(buf, "\r\n\r\n");
    if (!body) { free(buf); return NULL; }
    body += 4;

    /* Handle chunked transfer encoding */
    char *te = strstr(buf, "Transfer-Encoding: chunked");
    if (te && te < body) {
        char *result = (char *)malloc(buf_len + 1);
        size_t rlen = 0;
        char *p = body;
        while (*p) {
            json_skip_whitespace((const char **)&p);
            char *ep;
            long chunk_size = strtol(p, &ep, 16);
            if (chunk_size <= 0) break;
            p = ep;
            while (*p == '\r' || *p == '\n' || *p == ' ' || *p == '\t') p++;
            memcpy(result + rlen, p, chunk_size);
            rlen += chunk_size;
            p += chunk_size;
            while (*p == '\r' || *p == '\n') p++;
        }
        result[rlen] = '\0';
        free(buf);
        return result;
    }

    char *result = (char *)malloc(buf_len + 1);
    size_t body_len = buf_len - (size_t)(body - buf);
    memcpy(result, body, body_len);
    result[body_len] = '\0';
    free(buf);
    return result;
}

