    g = g_groups;
    for (int i = 0; i < gcount; i++) { garr[i] = g; g = g->next; }
    qsort(garr, gcount, sizeof(ExtGroup *), cmp_ext);

    long total_files = 0, total_lines = 0, total_chars = 0;

    printf("=== File Tree Analysis ===\n");
    printf("\n");

    for (int i = 0; i < gcount; i++) {
        ExtGroup *grp = garr[i];
        printf("Extension: %s\n", grp->ext);
        printf("  Files: %d\n", grp->file_count);
        printf("  Total Lines: %ld\n", grp->total_lines);
        printf("  Total Characters: %ld\n", grp->total_chars);

        /* sort files by rel_path */
        FileEntry **farr = malloc(sizeof(FileEntry *) * grp->file_count);
        FileEntry *fe = grp->files;
        for (int j = 0; j < grp->file_count; j++) { farr[j] = fe; fe = fe->next; }
        qsort(farr, grp->file_count, sizeof(FileEntry *), cmp_file);

        for (int j = 0; j < grp->file_count; j++) {
            printf("    %s: %ld lines, %ld chars\n", farr[j]->rel_path, farr[j]->lines, farr[j]->chars);
