    g->total_lines = 0;
    g->total_chars = 0;
    g->next = g_groups;
    g_groups = g;
    return g;
}

static void add_file_to_group(ExtGroup *g, const char *rel_path, long lines, long chars) {
    FileEntry *fe = malloc(sizeof(FileEntry));
    fe->rel_path = dupstr(rel_path);
    fe->lines = lines;
    fe->chars = chars;
    fe->next = g->files;
    g->files = fe;
    g->file_count++;
    g->total_lines += lines;
    g->total_chars += chars;
}

static void process_file(const char *full_path, const char *rel_path) {
    FILE *fp = fopen(full_path, "rb");
    if (!fp) return;
    long lines = 0, chars = 0;
    char *buf = malloc(65536);
    size_t n;
    while ((n = fread(buf, 1, 65536, fp)) > 0) {
        chars += (long)n;
        for (size_t i = 0; i < n; i++) {
            if (buf[i] == '\n') lines++;
        }
    }
    free(buf);
    fclose(fp);

    /* determine extension */
    const char *fname = strrchr(rel_path, '/');
    fname = fname ? fname + 1 : rel_path;
    const char *dot = strrchr(fname, '.');
    const char *ext = dot ? dot : "";

    ExtGroup *g = find_or_create_group(ext);
    add_file_to_group(g, rel_path, lines, chars);
}

static void walk(const char *dir_path, const char *rel_prefix) {
    DIR *d = opendir(dir_path);
    if (!d) return;
    struct dirent *ent;
    size_t dlen = strlen(dir_path);
    while ((ent = readdir(d)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        char full_path[4096];
        snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, ent->d_name);

        struct stat st;
        if (lstat(full_path, &st) != 0) continue;

        if (S_ISLNK(st.st_mode)) continue;

        char rel[4096];
        if (rel_prefix[0] == '\0')
            snprintf(rel, sizeof(rel), "%s", ent->d_name);
        else
            snprintf(rel, sizeof(rel), "%s/%s", rel_prefix, ent->d_name);

        if (S_ISDIR(st.st_mode)) {
            walk(full_path, rel);
        } else if (S_ISREG(st.st_mode)) {
            process_file(full_path, rel);
        }
    }
    closedir(d);
}

static int cmp_ext(const void *a, const void *b) {
    ExtGroup *ga = *(ExtGroup **)a;
    ExtGroup *gb = *(ExtGroup **)b;
    return strcmp(ga->ext, gb->ext);
}

static int cmp_file(const void *a, const void *b) {
    FileEntry *fa = *(FileEntry **)a;
    FileEntry *fb = *(FileEntry **)b;
    return strcmp(fa->rel_path, fb->rel_path);
}

int main(void) {
    walk(BASE_DIR, "");

    /* collect groups into array for sorting */
    int gcount = 0;
    ExtGroup *g = g_groups;
    while (g) { gcount++; g = g->next; }

    ExtGroup **garr = malloc(sizeof(ExtGroup *) * (gcount > 0 ? gcount : 1));
    g = g_groups;
    for (int i = 0; i < gcount; i++) { garr[i] = g; g = g->next; }
    qsort(garr, gcount, sizeof(ExtGroup *), cmp_ext);

    long total_files = 0, total_lines = 0, total_chars = 0;

    printf("=== File Tree Analysis ===\n");
    printf("\n");

    for (int i = 0; i < gcount; i++) {
        ExtGroup *grp = garr[i];
        printf("Extension: %s\n", grp->ext);
        printf("  Files: %d\n", grp->file_count);
        printf("  Total Lines: %ld\n", grp->total_lines);
        printf("  Total Characters: %ld\n", grp->total_chars);

        /* sort files by rel_path */
        FileEntry **farr = malloc(sizeof(FileEntry *) * grp->file_count);
        FileEntry *fe = grp->files;
        for (int j = 0; j < grp->file_count; j++) { farr[j] = fe; fe = fe->next; }
        qsort(farr, grp->file_count, sizeof(FileEntry *), cmp_file);

        for (int j = 0; j < grp->file_count; j++) {
            printf("    %s: %ld lines, %ld chars\n", farr[j]->rel_path, farr[j]->lines, farr[j]->chars);
        }
        free(farr);

        total_files += grp->file_count;
        total_lines += grp->total_lines;
        total_chars += grp->total_chars;
    }

    printf("\n");
    printf("Total: %ld files, %ld lines, %ld characters\n", total_files, total_lines, total_chars);

    free(garr);
    return 0;
}
