import * as path from 'path';

const rootDir = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_a7ernmag/project_tree';

interface FileEntry {
    relPath: string;
    lines: number;
    chars: number;
}

function walkDir(dir: string, relative: string): FileEntry[] {
    const results: FileEntry[] = [];
    let entries: string[];
    try {
        entries = fs.readdirSync(dir);
    } catch {
        return results;
    }
    for (const entry of entries) {
        const fullPath = path.join(dir, entry);
        const relPath = relative ? relative + '/' + entry : entry;
        let stat: fs.Stats;
        try {
            stat = fs.lstatSync(fullPath);
        } catch {
            continue;
        }
        if (stat.isSymbolicLink()) {
            continue;
        }
        if (stat.isDirectory()) {
            results.push(...walkDir(fullPath, relPath));
        } else if (stat.isFile()) {
            const buf = fs.readFileSync(fullPath);
            const chars = buf.length;
            const content = buf.toString('utf-8');
            let lines = 0;
            if (content.length > 0) {
                lines = content.split('\n').length;
                if (content.endsWith('\n')) {
                    lines -= 1;
                }
            }
            results.push({ relPath, lines, chars });
        }
    }
    return results;
}

