func multiply(_ a: [[Int]], _ b: [[Int]]) -> [[Int]] {
    let n = a.count
    let p = b.count
    let m = b[0].count
    var c = [[Int]](repeating: [Int](repeating: 0, count: m), count: n)
    for i in 0..<n {
        for j in 0..<m {
            for k in 0..<p {
                c[i][j] += a[i][k] * b[k][j]
            }
        }
    }
    return c
}

func determinant(_ m: [[Int]]) -> Int {
    let n = m.count
    if n == 1 { return m[0][0] }
    if n == 2 { return m[0][0]*m[1][1] - m[0][1]*m[1][0] }
    var det = 0
    for j in 0..<n {
        var minor = [[Int]]()
        for i in 1..<n {
            var row = [Int]()
            for k in 0..<n {
                if k != j { row.append(m[i][k]) }
            }
            minor.append(row)
        }
        det += (j % 2 == 0 ? 1 : -1) * m[0][j] * determinant(minor)
    }
    return det
}

