use std::io::{Read, Write};
use std::net::TcpStream;

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

struct JsonParser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> JsonParser<'a> {
    fn new(input: &'a str) -> Self {
        JsonParser { input: input.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek_byte(&self) -> Option<u8> {
        if self.pos < self.input.len() { Some(self.input[self.pos]) } else { None }
    }

    fn advance(&mut self) -> Option<u8> {
        let b = self.peek_byte();
        if b.is_some() { self.pos += 1; }
        b
    }

    fn expect_byte(&mut self, c: u8) {
        self.skip_ws();
        let b = self.advance();
        if b != Some(c) {
            panic!("Expected '{}' but got {:?}", c as char, b);
        }
    }

    fn parse_value(&mut self) -> JsonValue {
        self.skip_ws();
        match self.peek_byte() {
            Some(b'"') => JsonValue::Str(self.parse_string()),
            Some(b'[') => JsonValue::Array(self.parse_array()),
            Some(b'{') => JsonValue::Object(self.parse_object()),
            Some(b't') => { self.expect_word(b"true"); JsonValue::Bool(true) }
            Some(b'f') => { self.expect_word(b"false"); JsonValue::Bool(false) }
            Some(b'n') => { self.expect_word(b"null"); JsonValue::Null }
            Some(c) if c == b'-' || c.is_ascii_digit() => JsonValue::Number(self.parse_number()),
            _ => panic!("Unexpected byte in JSON at pos {}", self.pos),
        }
    }

    fn expect_word(&mut self, word: &[u8]) {
        for &b in word {
            self.advance();
            // we already peeked the first char
        }
        // Actually let's just consume the bytes
        self.pos = self.pos; // already advanced
    }

    fn parse_string(&mut self) -> String {
        self.expect_byte(b'"');
        let mut result = String::new();
        loop {
            match self.advance() {
                None => panic!("Unterminated string"),
                Some(b'"') => break,
                Some(b'\\') => {
                    match self.advance() {
                        Some(b'"') => result.push('"'),
                        Some(b'\\') => result.push('\\'),
                        Some(b'/') => result.push('/'),
                        Some(b'n') => result.push('\n'),
                        Some(b'r') => result.push('\r'),
                        Some(b't') => result.push('\t'),
                        Some(b'b') => result.push('\u{0008}'),
                        Some(b'f') => result.push('\u{000C}'),
                        Some(b'u') => {
                            let cp = self.parse_hex4();
                            if cp >= 0xD800 && cp <= 0xDBFF {
                                // surrogate pair
                                self.expect_byte(b'\\');
                                self.expect_byte(b'u');
                                let cp2 = self.parse_hex4();
                                let combined = 0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00);
                                result.push(char::from_u32(combined).unwrap_or('\u{FFFD}'));
                            } else {
                                result.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                            }
                        }
                        Some(c) => result.push(c as char),
                        None => panic!("Unterminated escape"),
                    }
                }
                Some(c) => {
                    // Handle multi-byte UTF-8
                    if c < 0x80 {
                        result.push(c as char);
                    } else {
                        // Collect UTF-8 bytes
                        let mut bytes = vec![c];
                        let extra = if c >= 0xF0 { 3 } else if c >= 0xE0 { 2 } else { 1 };
                        for _ in 0..extra {
                            if let Some(b) = self.advance() {
                                bytes.push(b);
                            }
                        }
                        let s = String::from_utf8_lossy(&bytes);
                        result.push_str(&s);
                    }
                }
            }
        }
        result
    }

    fn parse_hex4(&mut self) -> u32 {
        let mut val: u32 = 0;
        for _ in 0..4 {
            let b = self.advance().expect("Expected hex digit");
            val = val * 16 + match b {
                b'0'..=b'9' => (b - b'0') as u32,
                b'a'..=b'f' => (b - b'a' + 10) as u32,
                b'A'..=b'F' => (b - b'A' + 10) as u32,
                _ => panic!("Invalid hex digit"),
            };
        }
        val
    }

    fn parse_number(&mut self) -> f64 {
        let start = self.pos;
        if self.peek_byte() == Some(b'-') { self.pos += 1; }
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        if self.pos < self.input.len() && self.input[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == b'e' || self.input[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == b'+' || self.input[self.pos] == b'-') { self.pos += 1; }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).expect("Invalid number");
        s.parse::<f64>().expect("Invalid number")
    }

    fn parse_array(&mut self) -> Vec<JsonValue> {
        self.expect_byte(b'[');
        let mut arr = Vec::new();
        self.skip_ws();
        if self.peek_byte() == Some(b']') {
            self.advance();
            return arr;
        }
        loop {
            arr.push(self.parse_value());
            self.skip_ws();
            match self.advance() {
                Some(b']') => break,
                Some(b',') => continue,
                _ => panic!("Expected , or ] in array"),
            }
        }
        arr
    }

    fn parse_object(&mut self) -> Vec<(String, JsonValue)> {
        self.expect_byte(b'{');
        let mut obj = Vec::new();
        self.skip_ws();
        if self.peek_byte() == Some(b'}') {
            self.advance();
            return obj;
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            self.expect_byte(b':');
            let val = self.parse_value();
            obj.push((key, val));
            self.skip_ws();
            match self.advance() {
                Some(b'}') => break,
                Some(b',') => continue,
                _ => panic!("Expected , or }} in object, got {:?}", self.peek_byte()),
            }
        }
        obj
    }
}

fn get_object_field<'a>(obj: &'a [(String, JsonValue)], key: &str) -> Option<&'a JsonValue> {
    obj.iter().find(|(k, _)| k == key).map(|(_, v)| v)
}

fn main() {
    // HTTP GET request
    let mut stream = TcpStream::connect("127.0.0.1:18924").expect("Failed to connect to server");
    stream.set_read_timeout(Some(10000)).expect("Failed to set timeout");
    let request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18924\r\nConnection: close\r\n\r\n";
    stream.write_all(request.as_bytes()).expect("Failed to send request");

    let mut response_bytes: Vec<u8> = Vec::new();
    stream.read_to_end(&mut response_bytes).expect("Failed to read response");
    drop(stream);

    let response = String::from_utf8_lossy(&response_bytes).to_string();

    // Find body after headers
    let body_str = if let Some(idx) = response.find("\r\n\r\n") {
        &response[idx + 4..]
    } else {
        panic!("Invalid HTTP response: no header separator found");
    };

    // Parse JSON
    let json = JsonParser::new(body_str.trim());
    let root = JsonParser::new(body_str.trim()).parse_value();

    let products = match root {
        JsonValue::Array(arr) => arr,
        _ => panic!("Expected JSON array at top level"),
    };

    // Extract (name, price) pairs
    let mut all_products: Vec<(String, f64)> = Vec::new();
    for item in &products {
        if let JsonValue::Object(obj) = item {
            let name = match get_object_field(obj, "name") {
                Some(JsonValue::Str(s)) => s.clone(),
                _ => continue,
            };
            let price = match get_object_field(obj, "price") {
                Some(JsonValue::Number(n)) => *n,
                _ => continue,
            };
            all_products.push((name, price));
        }
    }

    // Filter price > 50.00
    let mut filtered: Vec<(String, f64)> = all_products.into_iter()
        .filter(|(_, p)| *p > 50.00)
        .collect();

